local HatFeatherMaker = {}
local PRODUCTS = {
    iron_hat_feather = { name = "Železno pero za klobuke", ironCost = 1, woodCost = 1, leatherCost = 2, time = 5, cost = 165, prestige = 4, happiness = 2, description = "Železno pero za okras klobuka." },
    bronze_hat_feather = { name = "Bronasto pero za klobuke", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 2, time = 7, cost = 400, prestige = 6, happiness = 3, description = "Bronasto pero za klobučarje." },
    silver_hat_feather = { name = "Srebrno pero za klobuke", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 2, time = 11, cost = 970, prestige = 11, happiness = 4, description = "Srebrno pero za plemiške klobučarje." },
    gilded_hat_feather = { name = "Pozlačeno pero za klobuke", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 2, time = 15, cost = 2100, prestige = 20, happiness = 5, description = "Pozlačeno pero za dvorne klobučarje." },
    jewel_set_hat_feather = { name = "Draguljasto pero za klobuke", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 2, time = 19, cost = 4500, prestige = 36, happiness = 7, description = "Draguljasto pero za kraljeve klobučarje." },
    royal_sovereign_hat_feather = { name = "Kraljevski suvereno pero za klobuke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 2, time = 26, cost = 9700, prestige = 69, happiness = 13, description = "Suvereno pero z biseri za krono." },
}
local BUILDINGS = {
    hatfeather_workshop = { name = "Peresna delavnica", cost = { gold = 330, wood = 180, stone = 130, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    hatfeather_house = { name = "Peresna hiša", cost = { gold = 1200, wood = 360, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hatfeather_atelier = { name = "Mojstrski peresni atelje", cost = { gold = 3010, wood = 420, stone = 520, silver = 35, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_hatfeather_palace = { name = "Suverena peresna palača", cost = { gold = 13050, wood = 640, stone = 830, gold = 84, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
HatFeatherMaker.ironStock = 10; HatFeatherMaker.bronzeStock = 8; HatFeatherMaker.woodStock = 12; HatFeatherMaker.leatherStock = 14; HatFeatherMaker.silverStock = 8; HatFeatherMaker.goldStock = 6; HatFeatherMaker.jewelStock = 4; HatFeatherMaker.pearlStock = 4
HatFeatherMaker.productStock = {}; HatFeatherMaker.buildings = {}; HatFeatherMaker.maker = nil; HatFeatherMaker.activeMaking = {}; HatFeatherMaker.totalProducts = 0; HatFeatherMaker.dayTimer = 0
function HatFeatherMaker.init() HatFeatherMaker.ironStock=10; HatFeatherMaker.bronzeStock=8; HatFeatherMaker.woodStock=12; HatFeatherMaker.leatherStock=14; HatFeatherMaker.silverStock=8; HatFeatherMaker.goldStock=6; HatFeatherMaker.jewelStock=4; HatFeatherMaker.pearlStock=4; HatFeatherMaker.productStock={}; HatFeatherMaker.buildings={}; HatFeatherMaker.maker=nil; HatFeatherMaker.activeMaking={}; HatFeatherMaker.totalProducts=0; HatFeatherMaker.dayTimer=0; print("[HatFeatherMaker] Royal Hat Feather Maker System initialized (6 products, 4 buildings)") end
function HatFeatherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatFeatherMaker.maker={name=n or ("Peresar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peresar najet: %s (spretnost: %d)",HatFeatherMaker.maker.name,s),"success") end; return true end
function HatFeatherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatFeatherMaker.build(id) local ok,e=HatFeatherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatFeatherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatFeatherMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatFeatherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatFeatherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatFeatherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatFeatherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatFeatherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatFeatherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatFeatherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatFeatherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatFeatherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatFeatherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatFeatherMaker.buildings==0 then return false,"Potrebna peresna delavnica" end; if not HatFeatherMaker.maker then return false,"Potreben peresar" end; return true end
function HatFeatherMaker.make(pt,qty) qty=qty or 1; local ok,e=HatFeatherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatFeatherMaker.ironStock=HatFeatherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatFeatherMaker.bronzeStock=HatFeatherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatFeatherMaker.woodStock=HatFeatherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatFeatherMaker.leatherStock=HatFeatherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatFeatherMaker.silverStock=HatFeatherMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatFeatherMaker.goldStock=HatFeatherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatFeatherMaker.jewelStock=HatFeatherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatFeatherMaker.pearlStock=HatFeatherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatFeatherMaker.maker then t=math.max(1,t-math.floor(HatFeatherMaker.maker.skill/13)) end; table.insert(HatFeatherMaker.activeMaking,{id="hatfeather_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatFeatherMaker.completeMaking(m) local q=1.0+(HatFeatherMaker.getQualityBonus()/100); if HatFeatherMaker.maker then q=q+(HatFeatherMaker.maker.skill/140) end; q=math.min(2.5,q); HatFeatherMaker.productStock[m.productType]=(HatFeatherMaker.productStock[m.productType] or 0)+m.quantity; HatFeatherMaker.totalProducts=HatFeatherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatFeatherMaker.maker then HatFeatherMaker.maker.itemsMade=HatFeatherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatFeatherMaker.maker.skill=math.min(100,HatFeatherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pero izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hatfeather.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HatFeatherMaker.update(dt) if not _G.state then return end; HatFeatherMaker.dayTimer=HatFeatherMaker.dayTimer+dt; if HatFeatherMaker.dayTimer>=30 then HatFeatherMaker.dayTimer=0; for i=#HatFeatherMaker.activeMaking,1,-1 do local m=HatFeatherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatFeatherMaker.completeMaking(m); table.remove(HatFeatherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatFeatherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatFeatherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatFeatherMaker.getStats() return {ironStock=HatFeatherMaker.ironStock,bronzeStock=HatFeatherMaker.bronzeStock,woodStock=HatFeatherMaker.woodStock,leatherStock=HatFeatherMaker.leatherStock,silverStock=HatFeatherMaker.silverStock,goldStock=HatFeatherMaker.goldStock,jewelStock=HatFeatherMaker.jewelStock,pearlStock=HatFeatherMaker.pearlStock,productStock=HatFeatherMaker.productStock,numBuildings=#HatFeatherMaker.buildings,hasMaker=HatFeatherMaker.maker~=nil,makerName=HatFeatherMaker.maker and HatFeatherMaker.maker.name or "—",makerSkill=HatFeatherMaker.maker and HatFeatherMaker.maker.skill or 0,activeMaking=#HatFeatherMaker.activeMaking,totalProducts=HatFeatherMaker.totalProducts} end
return HatFeatherMaker
